//#region src/commands/init/templates.ts
const WEB_FRAMEWORK_CONFIG_TEMPLATE = `import { defineConfig } from '@apps-in-toss/web-framework/config';

export default defineConfig({
  appName: '%%appName%%',
  brand: {
    primaryColor: '#3182F6', // 화면에 노출될 앱의 기본 색상으로 바꿔주세요.
  },
  permissions: [],
  webBundleDir: '%%webBundleDir%%',
});
`;
//#endregion
//#region src/commands/init/index.ts
async function templateWebFramework({ appName, cwd, skipInput }) {
	const packageJsonPath = join(cwd, "package.json");
	const packageJsonRaw = await readFile(packageJsonPath, { encoding: "utf-8" });
	const packageJson = JSON.parse(packageJsonRaw);
	packageJson.scripts ??= {};
	if (packageJson.scripts.build) packageJson.scripts.build = packageJson.scripts.build + " && ait build";
	packageJson.scripts.deploy = "ait deploy";
	p.log.step(`${DEVTOOLS_PACKAGE_NAME}를 devDependencies에 추가하는 중...`);
	packageJson.devDependencies = {
		...packageJson.devDependencies,
		[DEVTOOLS_PACKAGE_NAME]: getDevtoolsVersionRange()
	};
	await writeFile(packageJsonPath, JSON.stringify(packageJson, null, 2), { encoding: "utf-8" });
	p.log.step(".gitignore 파일을 업데이트하는 중...");
	await appendFile(join(cwd, ".gitignore"), "\n*.ait\n");
	const webBundleDir = skipInput ? "dist" : await p.text({
		message: "웹 번들 결과물이 위치한 디렉토리를 입력해주세요.",
		placeholder: "dist",
		defaultValue: "dist"
	});
	if (p.isCancel(webBundleDir)) {
		p.cancel("초기화가 취소되었습니다");
		return;
	}
	p.log.step("apps-in-toss.config.ts 파일을 생성하는 중...");
	const config = transformTemplate(WEB_FRAMEWORK_CONFIG_TEMPLATE, {
		appName,
		webBundleDir
	});
	await writeFile(join(cwd, "apps-in-toss.config.ts"), config, { encoding: "utf-8" });
	await setupDevtoolsPlugin(cwd);
	await installDependencies(cwd);
}
/**
* 번들러 설정의 plugins 맨 앞에 devtools unplugin을 자동으로 꽂아줘요.
* 자동 주입이 어려운 모양이면 파일을 건드리지 않고 수동 안내만 보여줘요.
*/
async function setupDevtoolsPlugin(cwd) {
	const bundlerConfig = findBundlerConfig(cwd);
	if (bundlerConfig == null) {
		p.note(devtoolsManualGuide(), "devtools 수동 설치 안내");
		return;
	}
	const result = injectDevtoolsPlugin(await readFile(bundlerConfig.path, { encoding: "utf-8" }), bundlerConfig.path, bundlerConfig.bundler);
	switch (result.status) {
		case "transformed":
			await writeFile(bundlerConfig.path, result.source, { encoding: "utf-8" });
			p.log.step(`${basename(bundlerConfig.path)}에 devtools 플러그인을 추가했어요.`);
			break;
		case "already-installed":
			p.log.info("devtools 플러그인이 이미 설정되어 있어요.");
			break;
		case "needs-manual":
			p.log.warn(result.reason);
			p.note(devtoolsManualGuide(bundlerConfig.bundler), "devtools 수동 설치 안내");
			break;
	}
}
var InitCommand = class extends Command {
	static paths = [["init"]];
	static usage = Command.Usage({
		category: "Setup",
		description: t("init.description"),
		details: t("init.details"),
		examples: [[t("init.example.interactive.label"), "ait init"], [t("init.example.appName.label"), "ait init --app-name my-miniapp"]]
	});
	appName = Option.String("--app-name", {
		required: false,
		description: t("init.option.appName")
	});
	skipInput = Option.Boolean("--skip-input", {
		required: false,
		hidden: true
	});
	async execute() {
		const cwd = getPackageRoot(process.cwd());
		p.intro("🚀 앱 초기화를 시작합니다");
		const appName = await ensureSelect({
			value: this.appName,
			prompt: async () => p.text({
				message: "Enter app name",
				validate: (value) => {
					if (!value) return "앱 이름을 입력해주세요";
					const kebabCaseValue = kebabCase(value);
					if (value !== kebabCaseValue) return `앱 이름은 케밥-케이스 형식이어야 합니다 (예시: ${kebabCaseValue})`;
				}
			})
		});
		if (p.isCancel(appName)) {
			p.cancel("초기화가 취소되었습니다");
			return;
		}
		p.log.step(`앱 이름이 '${appName}'으로 설정되었습니다`);
		await templateWebFramework({
			appName,
			cwd,
			skipInput: this.skipInput ?? false
		});
		p.outro("✨ 초기화가 완료되었습니다!");
	}
};
