//#region src/utils/groupHelp.ts
/**
* Renders a styled "group help" page for a Command whose only job is to
* gather related subcommands under a shared path prefix (e.g. `ait token`
* grouping `token add`/`token remove`).
*
* Clipanion has no built-in notion of a "subcommand group": a bare group
* invocation just runs whatever `execute()` the group's own Command defines,
* and `<group> --help` normally resolves to clipanion's *ambiguous
* multi-match* help path (every registered command whose path starts with
* the given prefix) rather than anything group-shaped. This helper is meant
* to be called from that group Command's own `execute()` instead.
*
* It leans on clipanion's own rendering primitives — `cli.usage()` for each
* subcommand's usage line, `formatMarkdownish` for description text, and
* `cli.format()` for header/bold styling — so the output stays visually
* consistent with clipanion's native `--help` pages instead of hand-rolling
* ANSI output. `cli.format()`/`cli.usage()` already resolve color support
* the same way the rest of the CLI's help output does, so callers don't need
* to thread a `colored` flag through.
*
* The result always ends with the dim cross-locale discovery hint (see
* `helpHint()`), so every caller of this helper — the group's own bare
* invocation (e.g. `ait token`) and the `help` router (`ait help token` /
* `ait token --help`, rewritten to the same thing by `rewriteHelpArgv`) —
* automatically renders it without having to append it themselves.
*/
function renderGroupHelp(cli, groupUsage, subcommands, labels) {
	const format = cli.format();
	let result = ``;
	if (groupUsage.description) {
		result += formatMarkdownish(groupUsage.description, {
			format,
			paragraphs: false
		}).replace(/^./, (char) => char.toUpperCase());
		result += `\n`;
	}
	result += `\n`;
	result += `${format.header(labels.commandsHeader)}\n`;
	for (const subcommand of subcommands) {
		result += `\n`;
		result += cli.usage(subcommand);
		const description = subcommand.usage?.description;
		if (description) result += `    ${formatMarkdownish(description, {
			format,
			paragraphs: false
		})}`;
	}
	result += `\n`;
	result += formatMarkdownish(labels.detailHint, {
		format,
		paragraphs: true
	});
	result += `${colors.dim(helpHint())}\n`;
	return result;
}
