//#region src/utils/argv.ts
/**
* Rewrites any invocation that carries a bare `--help`/`-h` token into
* `["help", ...path]`, where `path` is the leading run of non-flag tokens
* that precede it (stopping at the first token that looks like a flag,
* i.e. starts with `-`).
*
* This lets a single registered command (`MainHelpCommand`, see
* `src/index.ts`) own every help surface instead of relying on clipanion's
* per-path internal help machinery, which:
*
*   - never instantiates a Command for `<command> --help` (it prints usage
*     directly from inside `Cli#run`, see `Command#help` in clipanion's
*     `advanced/Command.d.ts`), so that path can't be hooked to append the
*     cross-locale hint line (see `helpHint()` in `../i18n`).
*   - resolves `<group> --help` (e.g. `ait token --help`) through its
*     *ambiguous multi-match* help path whenever the prefix matches more
*     than one registered command (`token`, `token add`, `token remove`),
*     printing a generic "Multiple commands match your selection" listing
*     instead of anything specific to the group.
*
* Examples:
*   `["deploy", "--help"]`                    → `["help", "deploy"]`
*   `["token", "add", "-h"]`                   → `["help", "token", "add"]`
*   `["--help"]`                               → `["help"]`
*   `["token", "--help"]`                      → `["help", "token"]`
*   `["deploy", "--profile", "x", "--help"]`   → `["help", "deploy"]`
*     (the path stops at the first flag-like token, `--profile`, even
*     though that's not the `--help` token itself — everything from there
*     on is treated as options for whatever command the path names)
*
* `-h=<index>` (an explicit index into clipanion's ambiguous-match listing
* — e.g. `ait token -h=1`) is intentionally left untouched: it never
* matches the exact-token check below (it's the single string `"-h=1"`,
* not `"-h"`), so it keeps flowing through clipanion's original internal
* help machinery unchanged.
*
* Argv with no `--help`/`-h` token at all (the common case — an actual
* command invocation) is returned as a shallow copy, untouched.
*/
function rewriteHelpArgv(argv) {
	if (!argv.some((token) => token === `--help` || token === `-h`)) return [...argv];
	const path = [];
	for (const token of argv) {
		if (token.startsWith(`-`)) break;
		path.push(token);
	}
	return [`help`, ...path];
}
//#endregion
